// Guest CPU state and the operations that code generated by tools/lift.py uses.
//
// Everything here is inline so the compiler can fold it into the lifted
// functions. The few entry points that leave lifted code (calls through the
// address table, SVCs, traps) are declared at the end and defined by whoever
// links the lifted module: the runtime, or a test harness.
#pragma once

#include <algorithm>
#include <atomic>
#include <bit>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <limits>
#include <type_traits>

#if defined(_MSC_VER)
#include <intrin.h>
#endif

namespace rt {

namespace types {
using u8 = uint8_t;
using u16 = uint16_t;
using u32 = uint32_t;
using u64 = uint64_t;
using s8 = int8_t;
using s16 = int16_t;
using s32 = int32_t;
using s64 = int64_t;
} // namespace types
using namespace types;

struct Vec {
    u64 lo;
    u64 hi;
};

// Horizon gives a process a 39-bit address space. Guest addresses are masked
// to it, so a wild address faults inside the reservation instead of reaching
// host memory outside it.
inline constexpr u64 kAddressMask = (u64{1} << 39) - 1;

struct Cpu {
    u64 x[31];
    u64 sp;
    // Only kept up to date by a lift with --track-pc, for debugging.
    u64 pc;
    u8 nf, zf, cf, vf;
    Vec q[32];
    u64 fpcr, fpsr, tpidr, tpidrro;
    u8* mem;
    // Exclusive monitor: the address and value a load-exclusive observed.
    u64 excl_addr;
    u64 excl_value;
    bool excl_valid;
    // Owned by whoever runs the CPU (the runtime's thread state).
    void* host;
};

// Memory -------------------------------------------------------------------

inline u8* HostAddress(Cpu& c, u64 a) { return c.mem + (a & kAddressMask); }

template <class T>
inline T Ld(Cpu& c, u64 a) {
    T v;
    std::memcpy(&v, HostAddress(c, a), sizeof v);
    return v;
}

template <class T>
inline void St(Cpu& c, u64 a, T v) {
    std::memcpy(HostAddress(c, a), &v, sizeof v);
}

template <class T>
inline T LdAcq(Cpu& c, u64 a) {
    return std::atomic_ref<T>(*reinterpret_cast<T*>(HostAddress(c, a))).load(std::memory_order_acquire);
}

template <class T>
inline void StRel(Cpu& c, u64 a, T v) {
    std::atomic_ref<T>(*reinterpret_cast<T*>(HostAddress(c, a))).store(v, std::memory_order_release);
}

// Load/store exclusive. The store succeeds (returns 0) only if the monitor
// was armed for this address and the memory still holds the value the load
// saw; the compare-and-swap makes that check and the store one atomic step.
template <class T>
inline T LdExcl(Cpu& c, u64 a) {
    T v = std::atomic_ref<T>(*reinterpret_cast<T*>(HostAddress(c, a))).load(std::memory_order_acquire);
    c.excl_addr = a;
    c.excl_value = v;
    c.excl_valid = true;
    return v;
}

template <class T>
inline u32 StExcl(Cpu& c, u64 a, T v) {
    if (!c.excl_valid || c.excl_addr != a) {
        c.excl_valid = false;
        return 1;
    }
    c.excl_valid = false;
    T expected = static_cast<T>(c.excl_value);
    bool ok = std::atomic_ref<T>(*reinterpret_cast<T*>(HostAddress(c, a)))
                  .compare_exchange_strong(expected, v, std::memory_order_acq_rel);
    return ok ? 0 : 1;
}

// Flags --------------------------------------------------------------------

template <class T>
inline T AddWithCarry(Cpu& c, T a, T b, u32 carry) {
    constexpr int top = sizeof(T) * 8 - 1;
    T r = static_cast<T>(a + b + carry);
    c.nf = static_cast<u8>(r >> top);
    c.zf = r == 0;
    c.cf = carry ? r <= a : r < a;
    c.vf = static_cast<u8>(((~(a ^ b) & (a ^ r)) >> top) & 1);
    return r;
}

inline u64 Add64F(Cpu& c, u64 a, u64 b) { return AddWithCarry<u64>(c, a, b, 0); }
inline u32 Add32F(Cpu& c, u32 a, u32 b) { return AddWithCarry<u32>(c, a, b, 0); }
inline u64 Sub64F(Cpu& c, u64 a, u64 b) { return AddWithCarry<u64>(c, a, ~b, 1); }
inline u32 Sub32F(Cpu& c, u32 a, u32 b) { return AddWithCarry<u32>(c, a, ~b, 1); }
inline u64 Adc64F(Cpu& c, u64 a, u64 b, u32 carry) { return AddWithCarry<u64>(c, a, b, carry); }
inline u32 Adc32F(Cpu& c, u32 a, u32 b, u32 carry) { return AddWithCarry<u32>(c, a, b, carry); }

template <class T>
inline T LogicF(Cpu& c, T r) {
    c.nf = static_cast<u8>(r >> (sizeof(T) * 8 - 1));
    c.zf = r == 0;
    c.cf = 0;
    c.vf = 0;
    return r;
}

inline void SetNzcv(Cpu& c, u32 nzcv) {
    c.nf = (nzcv >> 3) & 1;
    c.zf = (nzcv >> 2) & 1;
    c.cf = (nzcv >> 1) & 1;
    c.vf = nzcv & 1;
}

// Integer helpers ----------------------------------------------------------

inline u64 Ror(u64 v, u64 r) { return std::rotr(v, static_cast<int>(r & 63)); }
inline u32 Ror(u32 v, u32 r) { return std::rotr(v, static_cast<int>(r & 31)); }

inline u64 Sdiv(u64 a, u64 b) {
    s64 x = static_cast<s64>(a), y = static_cast<s64>(b);
    if (y == 0) return 0;
    if (x == std::numeric_limits<s64>::min() && y == -1) return a;
    return static_cast<u64>(x / y);
}
inline u32 Sdiv(u32 a, u32 b) {
    s32 x = static_cast<s32>(a), y = static_cast<s32>(b);
    if (y == 0) return 0;
    if (x == std::numeric_limits<s32>::min() && y == -1) return a;
    return static_cast<u32>(x / y);
}

#if !defined(_MSC_VER)
__extension__ typedef unsigned __int128 u128;
__extension__ typedef __int128 s128;
#endif

inline u64 Umulh(u64 a, u64 b) {
#if defined(_MSC_VER)
    return __umulh(a, b);
#else
    return static_cast<u64>((static_cast<u128>(a) * b) >> 64);
#endif
}
inline u64 Smulh(u64 a, u64 b) {
#if defined(_MSC_VER)
    return static_cast<u64>(__mulh(static_cast<s64>(a), static_cast<s64>(b)));
#else
    return static_cast<u64>((static_cast<s128>(static_cast<s64>(a)) * static_cast<s64>(b)) >> 64);
#endif
}

template <class T>
inline T Clz(T v) { return static_cast<T>(std::countl_zero(v)); }
template <class T>
inline T Cls(T v) {
    using S = std::make_signed_t<T>;
    T x = v ^ static_cast<T>(static_cast<S>(v) >> 1);
    return static_cast<T>(std::countl_zero(x) - 1);
}

template <class T>
inline T Rbit(T v) {
    T r = 0;
    for (int i = 0; i < int(sizeof(T) * 8); ++i) r |= static_cast<T>(((v >> i) & 1) << (sizeof(T) * 8 - 1 - i));
    return r;
}

inline u32 ByteSwap(u32 v) { return (v >> 24) | ((v >> 8) & 0xff00) | ((v << 8) & 0xff0000) | (v << 24); }
inline u64 ByteSwap(u64 v) { return (u64{ByteSwap(static_cast<u32>(v))} << 32) | ByteSwap(static_cast<u32>(v >> 32)); }

inline u64 Rev(u64 v) { return ByteSwap(v); }
inline u32 Rev(u32 v) { return ByteSwap(v); }
inline u64 Rev32(u64 v) { return std::rotr(ByteSwap(v), 32); }
template <class T>
inline T Rev16(T v) {
    constexpr T m = static_cast<T>(0x00ff00ff00ff00ffull);
    return static_cast<T>(((v >> 8) & m) | ((v & m) << 8));
}

// Floating point -----------------------------------------------------------

inline double D(const Vec& v) { return std::bit_cast<double>(v.lo); }
inline Vec FromD(double d) { return Vec{std::bit_cast<u64>(d), 0}; }
inline u64 FloatBits(float f) { return std::bit_cast<u32>(f); }

// Host arithmetic gives the right finite and infinite results. NaNs follow
// the AArch64 rules instead of x86's: a signalling input is quietened and
// wins, then the first quiet input in operand order, and an invalid
// operation produces the positive default NaN.
inline constexpr u64 kDefaultNaN = 0x7ff8000000000000ull;
inline bool IsSNaN(double d) { return std::isnan(d) && !(std::bit_cast<u64>(d) & (u64{1} << 51)); }
inline double Quiet(double d) { return std::bit_cast<double>(std::bit_cast<u64>(d) | (u64{1} << 51)); }

inline double FpResult(double r, double a, double b) {
    if (IsSNaN(a)) return Quiet(a);
    if (IsSNaN(b)) return Quiet(b);
    if (std::isnan(a)) return a;
    if (std::isnan(b)) return b;
    return std::isnan(r) ? std::bit_cast<double>(kDefaultNaN) : r;
}
inline double Fadd(double a, double b) { return FpResult(a + b, a, b); }
inline double Fsub(double a, double b) { return FpResult(a - b, a, b); }
inline double Fmul(double a, double b) { return FpResult(a * b, a, b); }
inline double Fdiv(double a, double b) { return FpResult(a / b, a, b); }
// FMADD d = a + n * m, NaNs checked in the order a, n, m.
inline double Fmadd(double n, double m, double a) {
    bool inf_times_zero = (std::isinf(n) && m == 0.0) || (n == 0.0 && std::isinf(m));
    if (std::isnan(a) && !IsSNaN(a) && inf_times_zero) return std::bit_cast<double>(kDefaultNaN);
    for (double v : {a, n, m})
        if (IsSNaN(v)) return Quiet(v);
    for (double v : {a, n, m})
        if (std::isnan(v)) return v;
    double r = std::fma(n, m, a);
    return std::isnan(r) ? std::bit_cast<double>(kDefaultNaN) : r;
}

inline void Fcmp(Cpu& c, double a, double b) {
    if (std::isnan(a) || std::isnan(b)) SetNzcv(c, 0b0011);
    else if (a == b) SetNzcv(c, 0b0110);
    else if (a < b) SetNzcv(c, 0b1000);
    else SetNzcv(c, 0b0010);
}

// FCVTZS/FCVTZU: truncate, saturate, NaN to zero.
template <class I>
inline I FcvtTrunc(double d) {
    if (std::isnan(d)) return 0;
    double t = std::trunc(d);
    if (t <= static_cast<double>(std::numeric_limits<I>::min())) return std::numeric_limits<I>::min();
    if (t >= static_cast<double>(std::numeric_limits<I>::max())) return std::numeric_limits<I>::max();
    return static_cast<I>(t);
}
inline u64 Fcvtzs64(double d) { return static_cast<u64>(FcvtTrunc<s64>(d)); }
inline u32 Fcvtzs32(double d) { return static_cast<u32>(FcvtTrunc<s32>(d)); }
inline u64 Fcvtzu64(double d) { return FcvtTrunc<u64>(d); }
inline u32 Fcvtzu32(double d) { return FcvtTrunc<u32>(d); }

// Advanced SIMD --------------------------------------------------------------
// size is log2 of the element width in bytes; q selects 128 bits over 64.

struct Lanes {
    u8 b[16];
};
inline Lanes L(const Vec& v) { return std::bit_cast<Lanes>(v); }
inline Vec V(const Lanes& l) { return std::bit_cast<Vec>(l); }
inline Vec Narrow(Vec v, u32 q) { return q ? v : Vec{v.lo, 0}; }

inline u64 GetLane(const Lanes& l, u32 size, u32 i) {
    u64 v = 0;
    std::memcpy(&v, l.b + (i << size), size_t{1} << size);
    return v;
}
inline void SetLane(Lanes& l, u32 size, u32 i, u64 v) { std::memcpy(l.b + (i << size), &v, size_t{1} << size); }

inline Vec VAdd(Vec a, Vec b, u32 size, u32 q) {
    Lanes x = L(a), y = L(b), r{};
    for (u32 i = 0; i < (16u >> size); ++i) SetLane(r, size, i, GetLane(x, size, i) + GetLane(y, size, i));
    return Narrow(V(r), q);
}
inline Vec VCmeq(Vec a, Vec b, u32 size, u32 q) {
    Lanes x = L(a), y = L(b), r{};
    for (u32 i = 0; i < (16u >> size); ++i)
        SetLane(r, size, i, GetLane(x, size, i) == GetLane(y, size, i) ? ~u64{0} : 0);
    return Narrow(V(r), q);
}
inline Vec VAnd(Vec a, Vec b, u32 q) { return Narrow(Vec{a.lo & b.lo, a.hi & b.hi}, q); }
inline Vec VOrr(Vec a, Vec b, u32 q) { return Narrow(Vec{a.lo | b.lo, a.hi | b.hi}, q); }
inline Vec VNot(Vec a, u32 q) { return Narrow(Vec{~a.lo, ~a.hi}, q); }
inline Vec VBif(Vec d, Vec n, Vec m, u32 q) {
    return Narrow(Vec{d.lo ^ ((d.lo ^ n.lo) & ~m.lo), d.hi ^ ((d.hi ^ n.hi) & ~m.hi)}, q);
}
inline Vec VDup(u64 v, u32 size, u32 q) {
    Lanes r{};
    for (u32 i = 0; i < (16u >> size); ++i) SetLane(r, size, i, v);
    return Narrow(V(r), q);
}
inline u64 VLane(Vec v, u32 size, u32 i) { return GetLane(L(v), size, i); }
inline Vec VFnegD(Vec a, u32 q) { return Narrow(Vec{a.lo ^ (u64{1} << 63), a.hi ^ (u64{1} << 63)}, q); }
// REV32: reverse the size-wide elements inside each 32-bit word.
inline Vec VRev32(Vec a, u32 size, u32 q) {
    Lanes x = L(a), r{};
    u32 per = 4u >> size;
    for (u32 i = 0; i < (16u >> size); ++i) SetLane(r, size, i, GetLane(x, size, (i / per) * per + (per - 1 - i % per)));
    return Narrow(V(r), q);
}
// SHRN/SHRN2: narrow each 2*size-wide element of n, shifted right, into the
// lower (q=0, upper half cleared) or upper (q=1, lower half kept) half of d.
inline Vec VShrn(Vec d, Vec n, u32 size, u32 shift, u32 q) {
    Lanes x = L(n), r{};
    u32 count = 8u >> size;
    for (u32 i = 0; i < count; ++i) SetLane(r, size, i, GetLane(x, size + 1, i) >> shift);
    Vec half = V(r);
    return q ? Vec{d.lo, half.lo} : Vec{half.lo, 0};
}
inline Vec VUmaxv(Vec a, u32 size, u32 q) {
    Lanes x = L(a);
    u64 m = 0;
    for (u32 i = 0; i < ((q ? 16u : 8u) >> size); ++i) m = std::max(m, GetLane(x, size, i));
    return Vec{m, 0};
}
inline Vec VUminv(Vec a, u32 size, u32 q) {
    Lanes x = L(a);
    u64 m = ~u64{0};
    for (u32 i = 0; i < ((q ? 16u : 8u) >> size); ++i) m = std::min(m, GetLane(x, size, i));
    return Vec{m, 0};
}

struct Words {
    u32 w[4];
};
inline Words W4(Vec v) { return std::bit_cast<Words>(v); }
inline Vec FromW4(Words w) { return std::bit_cast<Vec>(w); }

inline Vec Sha256Hash(Vec xv, Vec yv, Vec wv, bool part1) {
    Words x = W4(xv), y = W4(yv), w = W4(wv);
    for (int e = 0; e < 4; ++e) {
        u32 chs = (y.w[0] & y.w[1]) ^ (~y.w[0] & y.w[2]);
        u32 maj = (x.w[0] & x.w[1]) ^ (x.w[0] & x.w[2]) ^ (x.w[1] & x.w[2]);
        u32 sigma_e = std::rotr(y.w[0], 6) ^ std::rotr(y.w[0], 11) ^ std::rotr(y.w[0], 25);
        u32 sigma_a = std::rotr(x.w[0], 2) ^ std::rotr(x.w[0], 13) ^ std::rotr(x.w[0], 22);
        u32 t = y.w[3] + sigma_e + chs + w.w[e];
        x.w[3] += t;
        y.w[3] = t + sigma_a + maj;
        // ROL(Y:X, 32)
        Words nx{{y.w[3], x.w[0], x.w[1], x.w[2]}};
        Words ny{{x.w[3], y.w[0], y.w[1], y.w[2]}};
        x = nx;
        y = ny;
    }
    return FromW4(part1 ? x : y);
}
inline Vec Sha256H(Vec d, Vec n, Vec m) { return Sha256Hash(d, n, m, true); }
inline Vec Sha256H2(Vec d, Vec n, Vec m) { return Sha256Hash(n, d, m, false); }
inline Vec Sha256Su0(Vec d, Vec n) {
    Words a = W4(d), b = W4(n), r{};
    u32 t[4] = {a.w[1], a.w[2], a.w[3], b.w[0]};
    for (int e = 0; e < 4; ++e) r.w[e] = (std::rotr(t[e], 7) ^ std::rotr(t[e], 18) ^ (t[e] >> 3)) + a.w[e];
    return FromW4(r);
}
inline Vec Sha256Su1(Vec d, Vec n, Vec m) {
    Words a = W4(d), b = W4(n), c = W4(m), r{};
    u32 t0[4] = {b.w[1], b.w[2], b.w[3], c.w[0]};
    auto sigma1 = [](u32 v) { return std::rotr(v, 17) ^ std::rotr(v, 19) ^ (v >> 10); };
    r.w[0] = sigma1(c.w[2]) + a.w[0] + t0[0];
    r.w[1] = sigma1(c.w[3]) + a.w[1] + t0[1];
    r.w[2] = sigma1(r.w[0]) + a.w[2] + t0[2];
    r.w[3] = sigma1(r.w[1]) + a.w[3] + t0[3];
    return FromW4(r);
}

// Leaving lifted code --------------------------------------------------------

using GuestFunction = void (*)(Cpu&);
struct FunctionEntry {
    u64 address;
    GuestFunction function;
};

// Calls the lifted function at a guest address (BLR, unrecognised BR).
void Call(Cpu& c, u64 target);
void Svc(Cpu& c, u32 imm, u64 pc);
u64 CounterTicks();
[[noreturn]] void Unimplemented(Cpu& c, u64 pc, u32 word);
[[noreturn]] void BadJump(Cpu& c, u64 pc, u64 target);

} // namespace rt

// Emitted by tools/lift.py for each module.
extern const rt::FunctionEntry rt_functions[];
extern const size_t rt_function_count;
extern const uint64_t rt_module_entry;
